  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the final price of a booking after reward evaluation. A fixed 20 percent discount applies only when the customer owns a membership package containing the DISCOUNTS award and the booking is made at least 24 hours before departure. The returned amount shall keep one decimal place. When the customer, membership package, booking time, or reward condition is invalid or missing, the original trip price shall be returned.
   * Algorithm:
   *   1. If customer is null, membershipPackage is null, or bookingTime is null, return this.price.
   *   2. If membershipPackage does not contain Award.DISCOUNTS, return this.price.
   *   3. Calculate the time difference between bookingTime and this.departureTime.
   *   4. If the difference is less than 24 hours, return this.price.
   *   5. Return Math.round(this.price * 0.8 * 10.0) / 10.0.
   * Related Features: price, departureTime
   * Related Classes: Customer, MembershipPackage, Award
   * Input: customer : Customer - the customer making the booking; bookingTime : String - the time when the booking is made, in "yyyy-MM-dd HH:mm" format
   * Output: double - the discounted price (one decimal place) or the original price
   * Pre-condition: None (null inputs return original price)
   * Post-condition: No state changes.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    // Step 1: If customer is null, membershipPackage is null, or bookingTime is null, return this.price.
    if (customer == null || customer.getMembershipPackage() == null || bookingTime == null)
    {
      return this.price;
    }

    // Step 2: If membershipPackage does not contain Award.DISCOUNTS, return this.price.
    if (!customer.getMembershipPackage().getAwards().contains(Award.DISCOUNTS))
    {
      return this.price;
    }

    // Step 3: Calculate the time difference between bookingTime and this.departureTime.
    // Times are in "yyyy-MM-dd HH:mm" format, which is lexicographically comparable.
    // Step 4: If the difference is less than 24 hours, return this.price.
    // "yyyy-MM-dd HH:mm" format: compare the string directly; if bookingTime >= departureTime, less than 24h difference means bookingTime is after departureTime
    // Actually, we need to check if bookingTime is at least 24 hours before departureTime.
    // Since the format is comparable as strings for the date part, but for time difference calculation,
    // we need to compute the difference. The simplest approach is to parse the strings.
    // But since the algorithm says "calculate the time difference", let's compare as strings.
    // For "yyyy-MM-dd HH:mm" format, we can compare lexicographically to determine ordering,
    // but for exact 24-hour difference, we need to parse.
    
    // Let's parse the strings to compute the difference in hours.
    // Format: "yyyy-MM-dd HH:mm"
    int bookingYear = Integer.parseInt(bookingTime.substring(0, 4));
    int bookingMonth = Integer.parseInt(bookingTime.substring(5, 7));
    int bookingDay = Integer.parseInt(bookingTime.substring(8, 10));
    int bookingHour = Integer.parseInt(bookingTime.substring(11, 13));
    int bookingMinute = Integer.parseInt(bookingTime.substring(14, 16));

    int departureYear = Integer.parseInt(this.departureTime.substring(0, 4));
    int departureMonth = Integer.parseInt(this.departureTime.substring(5, 7));
    int departureDay = Integer.parseInt(this.departureTime.substring(8, 10));
    int departureHour = Integer.parseInt(this.departureTime.substring(11, 13));
    int departureMinute = Integer.parseInt(this.departureTime.substring(14, 16));

    // Convert both to minutes since a reference point
    long bookingTotalMinutes = (long) bookingYear * 525600 + (long) bookingMonth * 43200 + (long) bookingDay * 1440 + (long) bookingHour * 60 + bookingMinute;
    long departureTotalMinutes = (long) departureYear * 525600 + (long) departureMonth * 43200 + (long) departureDay * 1440 + (long) departureHour * 60 + departureMinute;

    long diffMinutes = departureTotalMinutes - bookingTotalMinutes;

    // Step 4: If the difference is less than 24 hours (1440 minutes), return this.price.
    if (diffMinutes < 1440)
    {
      return this.price;
    }

    // Step 5: Return Math.round(this.price * 0.8 * 10.0) / 10.0.
    return Math.round(this.price * 0.8 * 10.0) / 10.0;
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Computes the reward points earned by a customer during a given month. Only customers whose membership package contains the POINTS award are eligible. Only bookings whose booking date falls inside the requested month shall be counted. Each booked seat contributes 5 points. Invalid inputs, missing membership packages, or unsupported rewards shall return 0.
   * Algorithm:
   *   1. If customer is null, customer.membershipPackage is null, or currentMonth is null, return 0.
   *   2. If membershipPackage does not contain Award.POINTS, return 0.
   *   3. Initialize totalPoints = 0.
   *   4. For each booking in customer.bookings:
   *      a. If booking.isInMonth(currentMonth) is true, add booking.numberOfSeats * 5 to totalPoints.
   *   5. Return totalPoints.
   * Related Features: bookings (via Customer), membershipPackage (via Customer)
   * Related Classes: Customer, MembershipPackage, Award, Booking
   * Input: currentMonth : String - the month in "yyyy-MM" format
   * Output: int - total reward points earned
   * Pre-condition: None (invalid inputs return 0)
   * Post-condition: No state changes.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    // Step 1: If customer is null, customer.membershipPackage is null, or currentMonth is null, return 0.
    if (customer == null || customer.getMembershipPackage() == null || currentMonth == null)
    {
      return 0;
    }

    // Step 2: If membershipPackage does not contain Award.POINTS, return 0.
    if (!customer.getMembershipPackage().getAwards().contains(Award.POINTS))
    {
      return 0;
    }

    // Step 3: Initialize totalPoints = 0.
    int totalPoints = 0;

    // Step 4: For each booking in customer.bookings:
    for (Booking booking : customer.getBookings())
    {
      // a. If booking.isInMonth(currentMonth) is true, add booking.numberOfSeats * 5 to totalPoints.
      if (booking.isInMonth(currentMonth))
      {
        totalPoints += booking.getNumberOfSeats() * 5;
      }
    }

    // Step 5: Return totalPoints.
    return totalPoints;
  }

